const fs = require('fs');
const path = require('path');

async function processCSVFiles() {
  const csvDir = '/data/csv/';
  const files = fs.readdirSync(csvDir).filter(f => f.endsWith('.csv')).sort();

  const allEvents = [];

  for (const file of files) {
    console.log(`Processing ${file}...`);
    const filePath = path.join(csvDir, file);
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.trim().split('\n');

    let dataLines = [];

    if (file === 'events_04.csv') {
      // Handle duplicate header row - remove the second header
      dataLines = lines.filter((line, index) => {
        if (index === 0) return false; // Skip first header
        if (line.includes('event_id,event_ts,user_id,event_type,value') && index > 0) {
          return false; // Skip duplicate header
        }
        return true;
      });
    } else {
      // Skip header row for all other files
      dataLines = lines.slice(1);
    }

    for (const line of dataLines) {
      if (!line.trim()) continue;

      let cleanLine = line;

      // Handle trailing comma in events_05.csv
      if (file === 'events_05.csv') {
        cleanLine = line.replace(/,$/, '');
      }

      const parts = cleanLine.split(',');
      if (parts.length < 5) continue;

      let [event_id, event_ts, user_id, event_type, value] = parts;

      // Handle date format in events_02.csv (DD/MM/YYYY to ISO-8601)
      if (file === 'events_02.csv') {
        const [day, month, year] = event_ts.split('/');
        event_ts = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T00:00:00Z`;
      }

      // Handle null values in events_03.csv and convert to 0
      if (file === 'events_03.csv' || value === 'N/A' || value === 'null' || value === '') {
        if (value === 'N/A' || value === 'null' || value === '') {
          value = '0';
        }
      }

      // Ensure value is a number
      const numericValue = parseFloat(value) || 0;

      const event = {
        event_id: event_id.trim(),
        event_ts: event_ts.trim(),
        user_id: user_id.trim(),
        event_type: event_type.trim(),
        value: numericValue
      };

      allEvents.push(event);
    }
  }

  console.log(`Total events to ingest: ${allEvents.length}`);

  // Wait for Moose to be ready
  await waitForMoose();

  // Ingest all events
  let successCount = 0;
  for (const event of allEvents) {
    try {
      const response = await fetch('http://localhost:4000/ingest/Events', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(event),
      });

      if (response.ok) {
        successCount++;
        if (successCount % 5 === 0) {
          console.log(`Ingested ${successCount}/${allEvents.length} events...`);
        }
      } else {
        console.error(`Failed to ingest event ${event.event_id}: ${response.status} ${response.statusText}`);
      }
    } catch (error) {
      console.error(`Error ingesting event ${event.event_id}:`, error.message);
    }
  }

  console.log(`Successfully ingested ${successCount}/${allEvents.length} events`);

  // Verify data in ClickHouse
  await verifyData();
}

async function waitForMoose() {
  console.log('Waiting for Moose to be ready...');
  let attempts = 0;
  const maxAttempts = 30;

  while (attempts < maxAttempts) {
    try {
      const response = await fetch('http://localhost:4000/health');
      if (response.ok) {
        console.log('Moose is ready!');
        return;
      }
    } catch (error) {
      // Service not ready yet
    }

    attempts++;
    console.log(`Attempt ${attempts}/${maxAttempts}...`);
    await new Promise(resolve => setTimeout(resolve, 2000));
  }

  throw new Error('Moose did not start within expected time');
}

async function verifyData() {
  console.log('Verifying data in ClickHouse...');
  try {
    const response = await fetch('http://localhost:18123/', {
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain',
      },
      body: 'SELECT COUNT(*) as count FROM analytics.events FORMAT JSON',
    });

    if (response.ok) {
      const result = await response.text();
      console.log('ClickHouse query result:', result);
    } else {
      console.log('ClickHouse query failed:', response.status, response.statusText);
    }
  } catch (error) {
    console.log('Error querying ClickHouse:', error.message);
  }
}

// Add fetch polyfill for Node.js
if (typeof fetch === 'undefined') {
  global.fetch = require('node-fetch');
}

processCSVFiles().catch(console.error);

